package jp.wakeguard.alarm;
import android.appwidget.*;import android.content.*;import android.widget.RemoteViews;
public class QuickToolsWidgetProvider extends AppWidgetProvider{
 static void update(Context c,AppWidgetManager m,int id){RemoteViews r=new RemoteViews(c.getPackageName(),R.layout.widget_quick_tools);r.setOnClickPendingIntent(R.id.q_alarm,WidgetSuite.open(c,MainActivity.class,null,null,30000+id));r.setOnClickPendingIntent(R.id.q_world,WidgetSuite.open(c,ClockActivity.class,"mode","world",30100+id));r.setOnClickPendingIntent(R.id.q_timer,WidgetSuite.open(c,ClockActivity.class,"mode","timer",30200+id));r.setOnClickPendingIntent(R.id.q_stopwatch,WidgetSuite.open(c,ClockActivity.class,"mode","stopwatch",30300+id));r.setOnClickPendingIntent(R.id.q_add,WidgetSuite.open(c,AlarmEditorActivity.class,null,null,30400+id));m.updateAppWidget(id,r);}public void onUpdate(Context c,AppWidgetManager m,int[] ids){for(int id:ids)update(c,m,id);}public void onAppWidgetOptionsChanged(Context c,AppWidgetManager m,int id,android.os.Bundle b){update(c,m,id);}}
